sql_query:
SELECT "Control regimen"
FROM clinical_trials
WHERE "Cancer type" = 'Non-Small Cell Lung' AND "Control arm" = 'Chemo' AND "Included in MA" = 'Yes' AND "Name of ICI" = 'Pembrolizumab';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Control regimen" AS source_value FROM clinical_trials WHERE "Cancer type" = 'Non-Small Cell Lung' AND "Control arm" = 'Chemo' AND "Included in MA" = 'Yes' AND "Name of ICI" = 'Pembrolizumab'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_control_backbone(source_value) AS "control_backbone"
FROM base;
